import{_ as r,l as o,o as e,c as s,v as t,p as n,x as l,d,i as c,S as h}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"背面与斜边清洗","description":"","frontmatter":{"title":"背面与斜边清洗","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/backside-bevel-clean.md","filePath":"litho/backside-bevel-clean.md","lastUpdated":1789023840000}'),p={name:"litho/backside-bevel-clean.md"};function B(_,a,E,b,m,u){const i=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="背面与斜边清洗" tabindex="-1">背面与斜边清洗 <a class="header-anchor" href="#背面与斜边清洗" aria-label="Permalink to &quot;背面与斜边清洗&quot;">​</a></h1><div class="epigraph"><p>胶和 BARC 会爬到斜边和背面。夹盘看见的脏，下一台设备还要看见。清洗是接触面合同，不是图形合同。</p><footer>—— 对照 backside rinse / bevel clean 在轨道上的公开步骤</footer></div><p><a href="/litho/wafer-edge-exposure">上一课</a>清正面边缘。缺口是光与 EBR 喷嘴够不着或故意留的斜边、背面。夹盘污染、热板接触不良、下一层 CVD 的边缘珠，都从这里起。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>旋涂时胶绕过斜边；搬运时正面液滴绕到背面。夹盘真空孔被堵、颗粒被压进背面再印到下一片正面。把这些写成「环境颗粒」，会漏掉可预测的爬胶路径。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>背面溶剂冲洗、斜边专用喷嘴、机械刷（谨慎，刮伤风险）。与 EBR 溶剂可能同一化学、不同几何。清洗后要检查夹盘残留与真空泄漏率。双面都有膜的工艺（某些堆积）不能乱冲——配方绑定层次。</p>',7)),(e(),n(h,null,{default:l(()=>[c(i,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20WRAP%5B%22%E7%88%AC%E8%83%B6%20%2F%20%E7%BB%95%E6%B6%B2%22%5D%20--%3E%20BS%5B%22%E8%83%8C%E9%9D%A2%E5%86%B2%E6%B4%97%22%5D%0A%20%20WRAP%20--%3E%20BV%5B%22%E6%96%9C%E8%BE%B9%E6%B8%85%E6%B4%97%22%5D%0A%20%20BS%20--%3E%20CHUCK%5B%22%E5%A4%B9%E7%9B%98%E6%B8%85%E6%B4%81%22%5D%0A%20%20BV%20--%3E%20CHUCK%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p><span class="marginnote">斜边是应力与剥离的起点，也是金属污染的高速公路。清洗过猛会在斜边留下锯齿膜，后续剥离更差。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>离心与表面润湿把液体带到背面。毛细沿斜边缝爬。清洗是反向润湿+旋转甩出。残留膜在高温模块碳化成颗粒。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>下一课 BARC 开口：回到正面图形转印，假定背面已可夹。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>背面与斜边清洗保护夹盘与下游腔体。</li><li>与正面 EBR / WEE 几何不同，常被漏检。</li><li>出处：backside / bevel clean 通识。</li></ul>',7))])}const C=r(p,[["render",B]]);export{A as __pageData,C as default};
